        description: "Born of Spartan blood and wed to the ruthless Agamemnon, Queen Clytemnestra rules Mycenae with an iron will, orchestrating bloody retribution for her sacrificed daughter.",
        cardOverview: "The fiercely intelligent Spartan queen orchestrates bloody justice against the brutal conquerors of Mycenae.",
